<?php
declare(strict_types=1); namespace Comfino\Shop\Order\Cart; class Product implements ProductInterface{ private $name; private $price; private $id; private $category; private $ean; private $photoUrl; private $categoryIds; private $netPrice; private $taxRate; private $taxValue; public function __construct(string $name,int $price,?string $id=null,?string $category=null,?string $ean=null,?string $photoUrl=null,?array$categoryIds=null,?int $netPrice=null,?int $taxRate=null,?int $taxValue=null){$this->name=$name;$this->price=$price;$this->id=$id;$this->category=$category;$this->ean=$ean;$this->photoUrl=$photoUrl;$this->categoryIds=$categoryIds;$this->netPrice=$netPrice;$this->taxRate=$taxRate;$this->taxValue=$taxValue;}public function getName():string{return trim(html_entity_decode(strip_tags($this->name)));}public function getPrice():int{return $this->price;}public function getNetPrice():?int{return $this->netPrice;}public function getTaxRate():?int{return $this->taxRate;}public function getTaxValue():?int{return $this->taxValue;}public function getId():?string{return $this->id!==null?trim(strip_tags($this->id)):null;}public function getCategory():?string{return $this->category!==null?trim(strip_tags($this->category)):null;}public function getEan():?string{return $this->ean!==null?trim(strip_tags($this->ean)):null;}public function getPhotoUrl():?string{return $this->photoUrl!==null?trim(strip_tags($this->photoUrl)):null;}public function getCategoryIds():?array{return $this->categoryIds;}}